    "description": "پیکربندی کانتینر داکر با EXPOSE 10000",
    "content": "FROM python:3.11-slim\n\nWORKDIR /app\n\nENV PYTHONDONTWRITEBYTECODE=1 \\\n    PYTHONUNBUFFERED=1 \\\n    PYTHONPATH=/app \\\n    PORT=10000\n\nCOPY requirements.txt .\nRUN pip install --no-cache-dir -r requirements.txt\n\nCOPY . /app\n\nEXPOSE 10000\n\nCMD [\"python\", \"main.py\"]\n"
